import subprocess

def check_and_unsubscribe(email):
    # Überprüfen, ob die E-Mail in der Datenbank vorhanden ist
    if is_email_in_database(email):
        return 1
    else:
        # Skript aufrufen, das die E-Mail abbestellt
        result = subprocess.run(['./unsubscribe_script.sh', email], capture_output=True, text=True)
        if result.returncode == 0:
            return 1
        else:
            return 0

def is_email_in_database(email):
    # Beispiel-Implementierung: Hier würde eine Datenbankabfrage stattfinden
    # Für dieses Beispiel wird angenommen, dass die E-Mail in der Datenbank ist, wenn sie nicht 'test@example.com' ist
    # In der realen Anwendung würde hier eine Datenbankabfrage erfolgen
    return email == "test@example.com"  # Beispielbedingung

