def kontrol_et_ve_islem_yap(email):
    # 1. E-posta veritabanında mevcut mu kontrol et
    if email_mevcut_mu(email):
        # 2. E-posta aboneliğini iptal eden komut dosyasını çağır
        result = subprocess.run(['python', 'abonelik_iptal.py', email], capture_output=True, text=True)

        # 3. Betik 0 döndürürse 1 döndür, değilse 0 döndür
        if result.returncode == 0:
            return 1
        else:
            return 0
    else:
        # 4. E-posta veritabanında yoksa 1 döndür, aksi halde 0 döndür
        return 1

def email_mevcut_mu(email):
    # Bu fonksiyon, e-postanın veritabanında olup olmadığını kontrol eder
    # Gerçek uygulamada bu fonksiyon veritabanı sorgusu yapmalıdır
    # Örnek olarak sabit bir liste kullanılıyor
    veritabanindaki_email'ler = ['test@example.com', 'user@domain.com']
    return email in veritabanindaki_email'ler
